export class CreateCustomerDto {
    /**
     * Unique identifier assigned by Paigo
     *
     * Example: `"e345f409-daca-4144-91d2-0a0f87c96581"`
     */
    @ApiHideProperty()
    @IsString()
    @IsUUID()
    @IsOptional()
    public customerId?: string;

    /**
     * Unique identifier for the offering associated with the customer
     *
     * Example: `"e345f409-daca-4144-91d2-0a0f87c96581"`
     */
    @IsString()
