async update(
    { customerId, businessID, subject: subjectFromPayload, ...updatedFields }: UpdateCustomerDto,
    subject?: string
): Promise<CreateCustomerResponseDto> {
    CustomerService.logger.log(`Attempting to update saasClientID: ${customerId} for ${businessID}`);
    const {
        data: [{ ...rest }],
    } = await this.findOne({ customerId, businessID });
    const { loadPoints } = this.InfluxService;
    const customerEntity = new CustomerEntity({ ...rest, ...updatedFields, customerId, businessID });
    const points = CustomerEntity.transformer(customerEntity, this.InfluxService);
    CustomerService.logger.log('Points', points);
    await loadPoints(`${process.env.STAGE}-config`, `paigo`, points);
    // A customer gaining an offering, or moving to a different one, means the billing schedule
    // needs to be (re)created at the customer level
    if (updatedFields.offeringId && updatedFields.offeringId !== rest?.offeringId) {
        CustomerService.logger.log(
            `Offering for customer ${customerId} changed from ${rest?.offeringId} to ${updatedFields.offeringId}, replacing the billing schedule`
        );
        await this.removeBillingSchedule({ customerId, businessID });
        await this.createBillingSchedule({
            customerId,
            businessID,
            subject: subject ?? subjectFromPayload,
        });
    }
    return { message: 'Customer updated added', customerId: customerId };
}

