import { Inject, Logger, forwardRef } from '@nestjs/common';
import { InfluxService } from '../influx/influx.service';
import { InvoicesService } from '../invoice/invoices.service';
import { Billing, billingScheduleConsumers } from './entities/billing.entity';
import { randomUUID } from 'crypto';
import { Process, Processor } from '@nestjs/bull';
import { CreateBillingReportDto } from './dto/createBillingReport.dto';
import { Job } from 'bull';
import { SchedulerEntity } from '../scheduler/entities/scheduler.entity';
import { CustomerService } from '../customer/customer.service';
import { AuditService } from '../audit/audit.service';
import { AuditScope } from '../audit/entities/audit.interface';

@Processor('scheduler_billing_queue')
export class BillingService {
    private static readonly logger = new Logger(BillingService.name);
    constructor(
        readonly InfluxService: InfluxService,
        @Inject(forwardRef(() => CustomerService)) readonly customerService: CustomerService,
        @Inject(forwardRef(() => InvoicesService)) readonly invoicesService: InvoicesService
    ) {}
    @Process({ name: billingScheduleConsumers.billingReport })
    async create({ data: { scheduleParameters, businessID: schedulerBusinessID } }: Job<SchedulerEntity>) {
        // 1. Called via the scheduler, the job holds the businessID and the customerId gets set when a customer is created / updated
        const { customerId, businessID: parameterBusinessID } = (scheduleParameters ||
            {}) as CreateBillingReportDto;
        const businessID = schedulerBusinessID || parameterBusinessID;
        try {
            // 2. Billing is done at the customer level, the offering attached to the customer describes what to bill
            const {
                data: [customer],
            } = await this.customerService.findOne({ businessID, customerId });
            const offering = customer?.offering;
            if (offering) {
                // 3. The billing cycle of the offering determines the time range the usage is billed for
                const { startTime, endTime } = Billing.billingCycleToTimeRange(offering.billingCycle);
                BillingService.logger.log(
                    `Generating an invoice for customer: ${customerId} in business: ${businessID} between ${startTime} and ${endTime}`
                );
                // 4. Create the Invoice off of the total usage of the customer for the billing cycle
                const { invoiceId } = await this.invoicesService.generateInvoiceForUsageTotal({
                    businessID,
                    customerId,
                    start: startTime,
                    end: endTime,
                });
                const entity = new Billing({
                    invoiceId,
                    businessID,
                    customerId,
                    startTime,
                    endTime,
                    billingId: randomUUID(),
                });
                // 5. Save Billing information to the Ledger
                const point = Billing.transformer(entity, this.InfluxService);
                await this.InfluxService.loadPoints(`${process.env.STAGE}-aggregate-usage`, 'paigo', [point]);
            } else {
                BillingService.logger.log(
                    `No offering found for customer:${customerId} in business: ${businessID}, nothing to bill`
                );
            }
        } catch (error) {
            BillingService.logger.error(
                `Error occurred while generating the billing report for customer: ${customerId} in business: ${businessID}`,
                error?.stack
            );
            AuditService.publishEvent({
                message: `Error occurred while generating the billing report for customer: ${customerId} in business: ${businessID}`,
                topic: AuditScope.ERROR,
                data: [error],
            });
        }
    }
}

