import { NotFoundException } from '@nestjs/common';
import { BillingService } from './billing.service';
import { CustomerService } from '../customer/customer.service';
import { UsageService } from '../usage/usage.service';
import { SchedulerService } from '../scheduler/scheduler.service';
import { AuditService } from '../audit/audit.service';
import { schedulerType, SchedulerStatus, SupportedMeasurementFrequencies } from '../scheduler/dto/scheduler.dto';

const influxMock = () =>
    ({
        loadPoints: jest.fn(),
        getPoint: jest.fn().mockReturnValue({ stringField: jest.fn(), tag: jest.fn() }),
    } as any);

describe('scratch: billing migration', () => {
    it('bills the customer offering and stores the invoiceId', async () => {
        const influx = influxMock();
        const customerService = {
            findOne: jest.fn().mockResolvedValue({
                data: [{ customerId: 'cust', offering: { billingCycle: 'monthly' } }],
            }),
        };
        const invoicesService = { generateInvoiceForUsageTotal: jest.fn().mockResolvedValue({ invoiceId: 'inv-1' }) };
        const service = new BillingService(influx, customerService as any, invoicesService as any);
        await service.create({
            data: { businessID: 'biz', scheduleParameters: { customerId: 'cust' } },
        } as any);
        expect(customerService.findOne).toHaveBeenCalledWith({ businessID: 'biz', customerId: 'cust' });
        const args = invoicesService.generateInvoiceForUsageTotal.mock.calls[0][0];
        expect(args.businessID).toBe('biz');
        expect(args.customerId).toBe('cust');
        expect(args.start).toEqual(expect.any(String));
        expect(args.end).toEqual(expect.any(String));
        expect(influx.loadPoints).toHaveBeenCalled();
    });

    it('publishes an audit event on failure and does not store a record', async () => {
        const influx = influxMock();
        const spy = jest.spyOn(AuditService, 'publishEvent').mockImplementation(() => undefined);
        const customerService = {
            findOne: jest.fn().mockResolvedValue({ data: [{ offering: { billingCycle: 'monthly' } }] }),
        };
        const invoicesService = {
            generateInvoiceForUsageTotal: jest.fn().mockRejectedValue(new Error('boom')),
        };
        const service = new BillingService(influx, customerService as any, invoicesService as any);
        await expect(
            service.create({ data: { businessID: 'biz', scheduleParameters: { customerId: 'cust' } } } as any)
        ).resolves.toBeUndefined();
        expect(spy).toHaveBeenCalled();
        expect(influx.loadPoints).not.toHaveBeenCalled();
        spy.mockRestore();
    });

    it('skips customers without an offering', async () => {
        const influx = influxMock();
        const customerService = { findOne: jest.fn().mockResolvedValue({ data: [{ customerId: 'cust' }] }) };
        const invoicesService = { generateInvoiceForUsageTotal: jest.fn() };
        const service = new BillingService(influx, customerService as any, invoicesService as any);
        await service.create({ data: { businessID: 'biz', scheduleParameters: { customerId: 'cust' } } } as any);
        expect(invoicesService.generateInvoiceForUsageTotal).not.toHaveBeenCalled();
        expect(influx.loadPoints).not.toHaveBeenCalled();
    });
});

describe('scratch: customer schedules', () => {
    const buildCustomerService = (scheduler) =>
        new CustomerService(
            { loadPoints: jest.fn(), getPoint: () => ({ tag: jest.fn(), stringField: jest.fn() }) } as any,
            scheduler as any,
            {} as any,
            {} as any,
            {} as any
        );

    it('creates a schedule only when the customer has an offering', async () => {
        const scheduler = { create: jest.fn(), remove: jest.fn() };
        const service = buildCustomerService(scheduler);
        await service.create({ customerName: 'c', businessID: 'biz' } as any, 'subject|1');
        expect(scheduler.create).not.toHaveBeenCalled();
        await service.create({ customerName: 'c', businessID: 'biz', offeringId: 'off' } as any, 'subject|1');
        expect(scheduler.create).toHaveBeenCalledWith(
            expect.objectContaining({
                schedulerType: schedulerType.billing,
                schedulerStatus: SchedulerStatus.live,
                rate: SupportedMeasurementFrequencies.monthly,
                subject: 'subject|1',
                businessID: 'biz',
            })
        );
    });

    it('replaces the schedule when the offering changes, tolerating a missing schedule', async () => {
        const scheduler = {
            create: jest.fn(),
            remove: jest.fn().mockRejectedValue(new NotFoundException('nope')),
        };
        const service = buildCustomerService(scheduler);
        jest.spyOn(service, 'findOne').mockResolvedValue({
            data: [{ customerId: 'cust', customerName: 'c' } as any],
            message: 'Found Customer',
        });
        await service.update({ customerId: 'cust', businessID: 'biz', offeringId: 'off' } as any, 'subject|1');
        expect(scheduler.remove).toHaveBeenCalledWith({
            schedulerID: 'cust',
            businessID: 'biz',
            isBillingQueue: true,
        });
        expect(scheduler.create).toHaveBeenCalledWith(
            expect.objectContaining({ schedulerID: 'cust', subject: 'subject|1', businessID: 'biz' })
        );
    });

    it('does not touch the schedule when the offering is unchanged', async () => {
        const scheduler = { create: jest.fn(), remove: jest.fn() };
        const service = buildCustomerService(scheduler);
        jest.spyOn(service, 'findOne').mockResolvedValue({
            data: [{ customerId: 'cust', customerName: 'c', offeringId: 'off' } as any],
            message: 'Found Customer',
        });
        await service.update({ customerId: 'cust', businessID: 'biz', offeringId: 'off' } as any, 'subject|1');
        expect(scheduler.remove).not.toHaveBeenCalled();
        expect(scheduler.create).not.toHaveBeenCalled();
    });
});

describe('scratch: usage without offering', () => {
    it('returns an empty result', async () => {
        const usageService = new UsageService(
            {} as any,
            {} as any,
            {} as any,
            { findOne: jest.fn().mockResolvedValue({ data: [{ customerId: 'cust' }] }) } as any,
            {} as any
        );
        await expect(usageService.findUsageForCustomer({ customerId: 'cust', businessID: 'biz' }, {})).resolves.toEqual(
            []
        );
    });
});

describe('scratch: scheduler emit routing', () => {
    it('routes billing emissions to the billing queue', async () => {
        const queue = { add: jest.fn() };
        const billingQueue = { add: jest.fn() };
        const service = new SchedulerService(queue as any, billingQueue as any);
        await service.emitOne({
            schedulerId: 'sched',
            payload: { schedulerType: schedulerType.billing, scheduleParameters: { customerId: 'cust' } },
        });
        expect(billingQueue.add).toHaveBeenCalledWith('billingReport', expect.anything());
        expect(queue.add).not.toHaveBeenCalled();

        await service.emitOne({
            schedulerId: 'sched2',
            payload: { schedulerType: schedulerType.dimensionDataGathering, dimensionType: 'ebsVolume' },
        });
        expect(queue.add).toHaveBeenCalledWith('ebsVolume', expect.anything());
        expect(billingQueue.add).toHaveBeenCalledTimes(1);
    });
});

