import { BillingService } from './billing.service';
import { AuditService } from '../audit/audit.service';
import { AuditScope } from '../audit/entities/audit.interface';
import { Billing } from './entities/billing.entity';

const buildInfluxMock = () =>
    ({
        loadPoints: jest.fn(),
        getPoint: jest.fn().mockReturnValue({ stringField: jest.fn(), tag: jest.fn() }),
    } as any);

const buildJob = (data) => ({ data } as any);

describe('BillingService billing report processing', () => {
    let auditSpy: jest.SpyInstance;

    beforeEach(() => {
        auditSpy = jest.spyOn(AuditService, 'publishEvent').mockImplementation(() => undefined);
    });

    afterEach(() => {
        auditSpy.mockRestore();
    });

    it('generates an invoice for the customer offering billing cycle and stores the billing record', async () => {
        const influxService = buildInfluxMock();
        const customerService = {
            findOne: jest
                .fn()
                .mockResolvedValue({ data: [{ customerId: 'customer-1', offering: { billingCycle: 'monthly' } }] }),
        };
        const invoicesService = {
            generateInvoiceForUsageTotal: jest.fn().mockResolvedValue({ invoiceId: 'invoice-1' }),
        };
        const transformerSpy = jest.spyOn(Billing, 'transformer');
        const service = new BillingService(influxService, customerService as any, invoicesService as any);

        await service.create(
            buildJob({ businessID: 'business-1', scheduleParameters: { customerId: 'customer-1' } })
        );

        const { startTime, endTime } = Billing.billingCycleToTimeRange('monthly' as any);
        expect(customerService.findOne).toHaveBeenCalledWith({ businessID: 'business-1', customerId: 'customer-1' });
        expect(invoicesService.generateInvoiceForUsageTotal).toHaveBeenCalledWith({
            businessID: 'business-1',
            customerId: 'customer-1',
            start: startTime,
            end: endTime,
        });
        expect(transformerSpy).toHaveBeenCalledWith(
            expect.objectContaining({
                invoiceId: 'invoice-1',
                businessID: 'business-1',
                customerId: 'customer-1',
                startTime,
                endTime,
            }),
            influxService
        );
        expect(influxService.loadPoints).toHaveBeenCalledTimes(1);
        expect(auditSpy).not.toHaveBeenCalled();
        transformerSpy.mockRestore();
    });

    it('does nothing when the customer has no offering', async () => {
        const influxService = buildInfluxMock();
        const customerService = { findOne: jest.fn().mockResolvedValue({ data: [{ customerId: 'customer-1' }] }) };
        const invoicesService = { generateInvoiceForUsageTotal: jest.fn() };
        const service = new BillingService(influxService, customerService as any, invoicesService as any);

        await service.create(
            buildJob({ businessID: 'business-1', scheduleParameters: { customerId: 'customer-1' } })
        );

        expect(invoicesService.generateInvoiceForUsageTotal).not.toHaveBeenCalled();
        expect(influxService.loadPoints).not.toHaveBeenCalled();
    });

    it('reports failures on the audit channel instead of storing a partial billing record', async () => {
        const influxService = buildInfluxMock();
        const error = new Error('invoice generation failed');
        const customerService = {
            findOne: jest.fn().mockResolvedValue({ data: [{ offering: { billingCycle: 'monthly' } }] }),
        };
        const invoicesService = { generateInvoiceForUsageTotal: jest.fn().mockRejectedValue(error) };
        const service = new BillingService(influxService, customerService as any, invoicesService as any);

        await expect(
            service.create(buildJob({ businessID: 'business-1', scheduleParameters: { customerId: 'customer-1' } }))
        ).resolves.toBeUndefined();

        expect(influxService.loadPoints).not.toHaveBeenCalled();
        expect(auditSpy).toHaveBeenCalledWith(
            expect.objectContaining({ topic: AuditScope.ERROR, data: [error] })
        );
    });
});

import { NotFoundException } from '@nestjs/common';
import { CustomerService } from './customer.service';
import { SchedulerStatus, SupportedMeasurementFrequencies, schedulerType } from '../scheduler/dto/scheduler.dto';

const buildService = (scheduler) =>
    new CustomerService(
        { loadPoints: jest.fn(), getPoint: () => ({ tag: jest.fn(), stringField: jest.fn() }) } as any,
        scheduler as any,
        {} as any,
        {} as any,
        {} as any
    );

describe('CustomerService billing schedules', () => {
    it('does not create a billing schedule for a customer without an offering', async () => {
        const scheduler = { create: jest.fn(), remove: jest.fn() };
        const service = buildService(scheduler);

        await service.create({ customerName: 'Wall Street Trading', businessID: 'business-1' } as any, 'auth0|1');

        expect(scheduler.create).not.toHaveBeenCalled();
    });

    it('creates a monthly customer level billing schedule when the customer has an offering', async () => {
        const scheduler = { create: jest.fn(), remove: jest.fn() };
        const service = buildService(scheduler);

        const { customerId } = await service.create(
            { customerName: 'Wall Street Trading', businessID: 'business-1', offeringId: 'offering-1' } as any,
            'auth0|1'
        );

        expect(scheduler.create).toHaveBeenCalledWith({
            schedulerID: customerId,
            schedulerType: schedulerType.billing,
            schedulerStatus: SchedulerStatus.live,
            scheduleParameters: { customerId, businessID: 'business-1' },
            rate: SupportedMeasurementFrequencies.monthly,
            subject: 'auth0|1',
            businessID: 'business-1',
        });
    });

    it('replaces the billing schedule when a customer gains an offering, tolerating a missing schedule', async () => {
        const scheduler = { create: jest.fn(), remove: jest.fn().mockRejectedValue(new NotFoundException('missing')) };
        const service = buildService(scheduler);
        jest.spyOn(service, 'findOne').mockResolvedValue({
            data: [{ customerId: 'customer-1', customerName: 'Wall Street Trading' } as any],
            message: 'Found Customer',
        });

        await service.update(
            { customerId: 'customer-1', businessID: 'business-1', offeringId: 'offering-1' },
            'auth0|1'
        );

        expect(scheduler.remove).toHaveBeenCalledWith({
            schedulerID: 'customer-1',
            businessID: 'business-1',
            isBillingQueue: true,
        });
        expect(scheduler.create).toHaveBeenCalledWith(
            expect.objectContaining({
                schedulerID: 'customer-1',
                schedulerType: schedulerType.billing,
                subject: 'auth0|1',
                businessID: 'business-1',
            })
        );
    });

    it('leaves the billing schedule alone when the offering does not change', async () => {
        const scheduler = { create: jest.fn(), remove: jest.fn() };
        const service = buildService(scheduler);
        jest.spyOn(service, 'findOne').mockResolvedValue({
            data: [
                { customerId: 'customer-1', customerName: 'Wall Street Trading', offeringId: 'offering-1' } as any,
            ],
            message: 'Found Customer',
        });

        await service.update({
            customerId: 'customer-1',
            businessID: 'business-1',
            offeringId: 'offering-1',
        });

        expect(scheduler.remove).not.toHaveBeenCalled();
        expect(scheduler.create).not.toHaveBeenCalled();
    });
});

import { SchedulerService } from './scheduler.service';
import { schedulerType } from './dto/scheduler.dto';
import { billingScheduleConsumers } from '../billing/entities/billing.entity';

describe('SchedulerService queue routing', () => {
    it('emits billing jobs onto the billing queue with the billing report consumer', async () => {
        const queue = { add: jest.fn() };
        const billingQueue = { add: jest.fn() };
        const service = new SchedulerService(queue as any, billingQueue as any);

        await service.emitOne({
            schedulerId: 'customer-1',
            payload: {
                schedulerType: schedulerType.billing,
                businessID: 'business-1',
                scheduleParameters: { customerId: 'customer-1' },
            },
        });

        expect(billingQueue.add).toHaveBeenCalledWith(
            billingScheduleConsumers.billingReport,
            expect.objectContaining({
                schedulerID: 'customer-1',
                businessID: 'business-1',
                scheduleParameters: { customerId: 'customer-1' },
            })
        );
        expect(queue.add).not.toHaveBeenCalled();
    });

    it('emits measurement jobs onto the scheduler queue with the dimension consumer', async () => {
        const queue = { add: jest.fn() };
        const billingQueue = { add: jest.fn() };
        const service = new SchedulerService(queue as any, billingQueue as any);

        await service.emitOne({
            schedulerId: 'schedule-1',
            payload: {
                schedulerType: schedulerType.dimensionDataGathering,
                dimensionType: 'ebsVolume',
                businessID: 'business-1',
                scheduleParameters: {},
            },
        });

        expect(queue.add).toHaveBeenCalledWith('ebsVolume', expect.objectContaining({ schedulerID: 'schedule-1' }));
        expect(billingQueue.add).not.toHaveBeenCalled();
    });
});

import { UsageService } from './usage.service';

describe('UsageService usage without an offering', () => {
    it('returns an empty result when the customer has no offering', async () => {
        const customerService = { findOne: jest.fn().mockResolvedValue({ data: [{ customerId: 'customer-1' }] }) };
